// Actual C3 read-only status aggregation. No provider is probed and no memory store is opened.
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {readFileSync,writeFileSync,readdirSync,mkdirSync,mkdtempSync,rmSync,existsSync} from 'node:fs';
import path from 'node:path';import {pathToFileURL} from 'node:url';
const root=process.env.PLUR1BUS_ENGINE_SRC;assert.ok(root);assert.equal(process.version,'v24.21.0');
const source=JSON.parse(readFileSync(new URL('./migrate-sources.json',import.meta.url),'utf8'));
const files=[];function walk(dir){for(const e of readdirSync(dir,{withFileTypes:true})){const f=path.join(dir,e.name);if(e.isDirectory())walk(f);else if(e.name.endsWith('.js'))files.push(f);}}
walk(path.join(root,'engine'));walk(path.join(root,'lib'));const hash=createHash('sha256');for(const f of files.sort()){hash.update(`${path.relative(root,f)}\0`);hash.update(readFileSync(f));hash.update('\0');}assert.equal(hash.digest('hex'),source.treeSha256);
import {tmpdir} from 'node:os';
const {createStoreMigrator}=await import(pathToFileURL(path.join(root,'engine/store/schema-version.js')));
const now=1800000000000,engineVersion='synthetic-engine';
const defs=[{name:'missing',missing:true},{name:'legacy-marker',schema:'0'},{name:'existing-no-marker',noMarker:true},{name:'current',schema:'1',from:'1',to:'1'},{name:'stale-from',schema:'1'},{name:'unknown-source',schema:'2',from:'2',to:'2'},{name:'downgrade',schema:'1',from:'1',to:'0'},{name:'unknown-target',to:'2'},{name:'invalid-from',from:'bad'},{name:'invalid-to',to:'bad'},{name:'fraction',to:'1.0'},{name:'negative',from:'-1'},{name:'empty-from',from:''},{name:'unreadable',raw:'{'},{name:'marker-directory',markerDirectory:true},{name:'marker-number',raw:'{"schemaVersion":1}'},{name:'leading-zero-noop',schema:'00',from:'00',to:'0'},{name:'leading-zero-step',schema:'00',from:'00',to:'01'},{name:'leading-zero-conflict',schema:'00',from:'0'},{name:'duplicate-json-last-wins',raw:'{"schemaVersion":"7","schemaVersion":"0"}'},{name:'repeat',repeat:true},{name:'same-current-no-write',schema:'1',from:'1',to:'01'}];
async function record(){const out=[];for(const d of defs){const base=mkdtempSync(path.join(tmpdir(),'rx3-migrate-'));try{if(d.missing)rmSync(base,{recursive:true});else if(d.noMarker)writeFileSync(path.join(base,'sentinel'),'unchanged');else if(d.markerDirectory)mkdirSync(path.join(base,'_schema.json'));else writeFileSync(path.join(base,'_schema.json'),d.raw??JSON.stringify({schemaVersion:d.schema??'0'}));const migrator=createStoreMigrator({baseDbPath:base,logger:{warn(){}},engineVersion,clock:()=>now});const results=[];async function call(from,to){try{results.push(await migrator.migrate(from,to));}catch(e){results.push({error:e.code??'unknown'});}}await call(d.from??'0',d.to??'1');if(d.repeat){await call('0','1');await call('1','1');}let marker=null;try{marker=readFileSync(path.join(base,'_schema.json'),'utf8');}catch{}out.push({...d,results,marker,current:migrator.current()});}finally{rmSync(base,{recursive:true,force:true});}}return out;}
const cases=await record();assert.deepEqual(await record(),cases);writeFileSync(new URL('./golden/migrate.json',import.meta.url),JSON.stringify({recordedFrom:{source,node:process.version},now,engineVersion,cases},null,2)+'\n');console.log(`Recorded ${cases.length} actual Node schema migration sequences twice`);
